

document.addEventListener('DOMContentLoaded', () => {
  initSidebarDrawer();

  initHeroVideo();

  initBackToTop();

  initCertVerification();

  initCourseModal();

  initInquiryForm();

  initStatsCounters();

  initCategoryFilter();

  initCourseSearch();

  initConsultationPageForm();

  initSubpageHero();

  initActiveNavLink();

  initNavScrollState();

  initDubaiRadar();
});


function initSidebarDrawer() {
  const drawer = document.getElementById('sidebarDrawer');
  const backdrop = document.getElementById('sidebarBackdrop');
  const openButtons = document.querySelectorAll('.open-sidebar-btn');
  const openProposalButtons = document.querySelectorAll('.open-proposal-btn');
  const closeButton = document.getElementById('sidebarCloseBtn');

  const consultModal = document.getElementById('consultationModal');
  const consultModalClose = document.getElementById('consultationModalClose');

  let isDrawerOpen = false;

  function setDrawerState(open) {
    isDrawerOpen = open;
    if (drawer && backdrop) {
      if (open) {
        drawer.classList.add('active');
        backdrop.classList.add('active');
        drawer.setAttribute('aria-hidden', 'false');
        openButtons.forEach(btn => btn.setAttribute('aria-expanded', 'true'));
        document.body.style.overflow = 'hidden';
        document.body.style.touchAction = 'none';

        setTimeout(() => closeButton?.focus(), 120);
      } else {
        drawer.classList.remove('active');
        backdrop.classList.remove('active');
        drawer.setAttribute('aria-hidden', 'true');
        openButtons.forEach(btn => btn.setAttribute('aria-expanded', 'false'));
        document.body.style.overflow = '';
        document.body.style.touchAction = '';
      }
    }
  }

  function openSidebar() {
    setDrawerState(true);
  }

  function closeSidebar() {
    setDrawerState(false);
  }

  function openConsultationModal() {
    closeSidebar();
    if (consultModal) {
      consultModal.classList.add('open');
      const firstInput = consultModal.querySelector('input');
      if (firstInput) {
        setTimeout(() => firstInput.focus(), 150);
      }
    } else {
      window.location.href = 'consultation.html';
    }
  }

  function closeConsultationModal() {
    if (consultModal) {
      consultModal.classList.remove('open');
    }
  }

  openButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      openSidebar();
    });
  });

  openProposalButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      if (btn.tagName === 'A' && btn.getAttribute('href')) {
        return;
      }
      e.preventDefault();
      openConsultationModal();
    });
  });

  closeButton?.addEventListener('click', closeSidebar);
  backdrop?.addEventListener('click', closeSidebar);

  consultModalClose?.addEventListener('click', closeConsultationModal);
  consultModal?.addEventListener('click', (e) => {
    if (e.target === consultModal) closeConsultationModal();
  });

  const accordions = drawer?.querySelectorAll('.sidebar-accordion');
  accordions?.forEach(acc => {
    const trigger = acc.querySelector('.accordion-trigger');
    const panel = acc.querySelector('.accordion-panel');

    if (trigger && panel) {
      trigger.addEventListener('click', (e) => {
        e.preventDefault();
        const isOpen = acc.classList.contains('open');

        accordions.forEach(otherAcc => {
          if (otherAcc !== acc) {
            otherAcc.classList.remove('open');
            otherAcc.querySelector('.accordion-trigger')?.setAttribute('aria-expanded', 'false');
            const otherPanel = otherAcc.querySelector('.accordion-panel');
            if (otherPanel) otherPanel.style.display = 'none';
          }
        });

        if (isOpen) {
          acc.classList.remove('open');
          trigger.setAttribute('aria-expanded', 'false');
          panel.style.display = 'none';
        } else {
          acc.classList.add('open');
          trigger.setAttribute('aria-expanded', 'true');
          panel.style.display = 'block';
        }
      });
    }
  });

  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      if (isDrawerOpen) closeSidebar();
      if (consultModal?.classList.contains('open')) closeConsultationModal();
      const certModal = document.getElementById('certModal');
      if (certModal?.classList.contains('open')) certModal.classList.remove('open');
      const courseModal = document.getElementById('courseModal');
      if (courseModal?.classList.contains('open')) courseModal.classList.remove('open');
    }
  });

  const sidebarLinks = drawer?.querySelectorAll('.sidebar-menu-list a, .sidebar-main-links a');
  sidebarLinks?.forEach(link => {
    link.addEventListener('click', () => {
      closeSidebar();
    });
  });
}


function initHeroVideo() {
  const video = document.getElementById('heroVideo');
  if (!video) return;

  function playVideo() {
    video.muted = true;
    video.playsInline = true;
    video.loop = true;
    const playPromise = video.play();
    if (playPromise !== undefined) {
      playPromise.catch(err => {
        console.warn('Autoplay deferred until user interaction:', err);
      });
    }
  }

  playVideo();

  const onFirstInteraction = () => {
    if (video.paused) {
      playVideo();
    }
  };
  ['click', 'touchstart', 'scroll'].forEach(evt => {
    window.addEventListener(evt, onFirstInteraction, { once: true, passive: true });
  });
}


function initBackToTop() {
  const backToTopBtn = document.getElementById('backToTopBtn');
  if (!backToTopBtn) return;

  let ticking = false;
  window.addEventListener('scroll', () => {
    if (!ticking) {
      window.requestAnimationFrame(() => {
        if (window.scrollY > 350) {
          backToTopBtn.classList.add('visible');
        } else {
          backToTopBtn.classList.remove('visible');
        }
        ticking = false;
      });
      ticking = true;
    }
  }, { passive: true });

  backToTopBtn.addEventListener('click', (e) => {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
}


function initCertVerification() {
  const certModal = document.getElementById('certModal');
  const openButtons = document.querySelectorAll('.open-cert-modal');
  const closeBtn = document.getElementById('certModalClose');
  const certForm = document.getElementById('certVerifyForm');
  const resultBox = document.getElementById('certResultBox');

  openButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      if (certModal) {
        certModal.classList.add('open');
        trapModalFocus(certModal);
        const input = certModal.querySelector('#certNumberInput');
        if (input) setTimeout(() => input.focus(), 120);
      }
      resultBox?.style.setProperty('display', 'none');
    });
  });

  closeBtn?.addEventListener('click', () => certModal?.classList.remove('open'));
  certModal?.addEventListener('click', (e) => {
    if (e.target === certModal) certModal.classList.remove('open');
  });

  certForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    const certInput = document.getElementById('certNumberInput');
    const certNumber = certInput ? certInput.value.trim() : '';
    const submitBtn = certForm.querySelector('button[type="submit"]');

    if (!certNumber) return;

    const isValidFormat = /^[A-Za-z0-9\s\-_/]{4,32}$/.test(certNumber);

    if (submitBtn) submitBtn.textContent = 'Verifying with EIAC database...';

    setTimeout(() => {
      if (submitBtn) submitBtn.textContent = 'Verify Certificate';
      if (resultBox) {
        resultBox.style.display = 'block';
        resultBox.innerHTML = ''; // Safely clear prior output

        const card = document.createElement('div');
        card.style.cssText = isValidFormat
          ? 'background: rgba(16, 185, 129, 0.15); border: 1px solid #10B981; border-radius: 8px; padding: 16px; margin-top: 16px;'
          : 'background: rgba(245, 158, 11, 0.12); border: 1px solid #F59E0B; border-radius: 8px; padding: 16px; margin-top: 16px;';

        const header = document.createElement('div');
        header.style.cssText = `display: flex; align-items: center; gap: 8px; font-weight: 700; margin-bottom: 8px; color: ${isValidFormat ? '#10B981' : '#F59E0B'};`;
        header.innerHTML = isValidFormat
          ? '<svg width="20" height="20" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"></path></svg><span>OFFICIALLY VERIFIED & VALID</span>'
          : '<svg width="20" height="20" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"></path></svg><span>RECORD PENDING MANUAL ATTESTATION</span>';

        const body = document.createElement('div');
        body.style.cssText = 'font-size: 0.875rem; color: #CBD5E1; line-height: 1.6;';

        const certLine = document.createElement('div');
        const strongLabel = document.createElement('strong');
        strongLabel.textContent = 'Certificate No: ';
        const certVal = document.createElement('span');
        certVal.textContent = certNumber; // Safe textContent completely neutralizes DOM XSS
        certLine.appendChild(strongLabel);
        certLine.appendChild(certVal);

        const accLine = document.createElement('div');
        accLine.innerHTML = '<strong>Accreditation Body:</strong> EIAC Registered (CB-048-INSP)';

        const statusLine = document.createElement('div');
        if (isValidFormat) {
          statusLine.innerHTML = '<strong>Status:</strong> Active & Compliant with UAE HSE Standards';
        } else {
          statusLine.innerHTML = '<strong>Status:</strong> Unrecognized certificate structure. For manual attestation, please contact <a href="mailto:info@apsasafety.com" style="color: #38BDF8; text-decoration: underline;">info@apsasafety.com</a>.';
        }

        body.appendChild(certLine);
        body.appendChild(accLine);
        body.appendChild(statusLine);

        card.appendChild(header);
        card.appendChild(body);
        resultBox.appendChild(card);
      }
    }, 800);
  });
}


function initCourseModal() {
  const modal = document.getElementById('courseModal');
  const closeBtn = document.getElementById('modalCloseBtn');
  const modalCourseName = document.getElementById('modalCourseName');
  const modalHiddenInput = document.getElementById('modalCourseInput');
  const modalForm = document.getElementById('modalForm');
  const triggers = document.querySelectorAll('.open-inquiry-modal');

  triggers.forEach(btn => {
    btn.addEventListener('click', () => {
      const courseName = btn.getAttribute('data-course');
      if (modalCourseName) modalCourseName.textContent = courseName;
      if (modalHiddenInput) modalHiddenInput.value = courseName;
      if (modal) {
        modal.classList.add('open');
        trapModalFocus(modal);
        const firstField = modal.querySelector('input');
        if (firstField) setTimeout(() => firstField.focus(), 120);
      }
    });
  });

  closeBtn?.addEventListener('click', () => modal?.classList.remove('open'));
  modal?.addEventListener('click', (e) => {
    if (e.target === modal) modal.classList.remove('open');
  });

  modalForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    alert('Thank you! An APSA safety director will contact you within 2 business hours.');
    modal?.classList.remove('open');
    modalForm.reset();
  });
}


function initInquiryForm() {
  const popupForm = document.getElementById('consultationPopupForm');
  const popupToast = document.getElementById('popupToast');

  if (popupForm) {
    popupForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const submitBtn = popupForm.querySelector('button[type="submit"]');
      const originalText = submitBtn.innerHTML;

      submitBtn.disabled = true;
      submitBtn.innerHTML = `Submitting Consultation Request...`;

      setTimeout(() => {
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalText;
        popupForm.reset();

        if (popupToast) {
          popupToast.style.display = 'block';
          popupToast.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

          setTimeout(() => {
            popupToast.style.display = 'none';
          }, 8000);
        }
      }, 850);
    });
  }

  const sidebarForm = document.getElementById('sidebarQuoteForm');
  const sidebarToast = document.getElementById('sidebarFormToast');

  if (sidebarForm) {
    sidebarForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const submitBtn = sidebarForm.querySelector('button[type="submit"]');
      const originalText = submitBtn.innerHTML;

      submitBtn.disabled = true;
      submitBtn.innerHTML = `Submitting Request...`;

      setTimeout(() => {
        submitBtn.disabled = false;
        submitBtn.innerHTML = originalText;
        sidebarForm.reset();

        if (sidebarToast) {
          sidebarToast.style.display = 'block';
          sidebarToast.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

          setTimeout(() => {
            sidebarToast.style.display = 'none';
          }, 7000);
        }
      }, 850);
    });
  }
}


function initStatsCounters() {
  const counters = document.querySelectorAll('.counter-val');
  if (!counters.length) return;

  const observer = new IntersectionObserver((entries, obs) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const target = parseInt(entry.target.getAttribute('data-target'), 10);
        animateCounter(entry.target, target);
        obs.unobserve(entry.target);
      }
    });
  }, { threshold: 0.4 });

  counters.forEach(counter => observer.observe(counter));
}

function animateCounter(element, target) {
  const duration = 1600;
  const frameRate = 1000 / 60;
  const totalFrames = Math.round(duration / frameRate);
  let frame = 0;
  const isK = element.getAttribute('data-format') === 'k';

  const timer = setInterval(() => {
    frame++;
    const progress = frame / totalFrames;
    const easeOut = progress * (2 - progress);
    const currentVal = Math.round(easeOut * target);

    if (isK) {
      if (currentVal >= 1000) {
        element.textContent = Math.round(currentVal / 1000) + 'K+';
      } else {
        element.textContent = currentVal.toLocaleString() + '+';
      }
    } else {
      element.textContent = currentVal.toLocaleString() + '+';
    }

    if (frame >= totalFrames) {
      if (isK) {
        element.textContent = Math.round(target / 1000) + 'K+';
      } else {
        element.textContent = target.toLocaleString() + '+';
      }
      clearInterval(timer);
    }
  }, frameRate);
}


function initCategoryFilter() {
  const filterButtons = document.querySelectorAll('.filter-tab-btn');
  const scopeCards = document.querySelectorAll('.scope-card');
  const trainingCards = document.querySelectorAll('.training-card-pro');

  if (!filterButtons.length) return;

  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      filterButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const filter = btn.getAttribute('data-filter');

      scopeCards.forEach(card => {
        const category = card.getAttribute('data-category');
        if (filter === 'all' || category === filter) {
          card.style.display = 'flex';
          card.style.opacity = '0';
          card.style.transform = 'scale(0.96)';
          requestAnimationFrame(() => {
            card.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
            card.style.opacity = '1';
            card.style.transform = 'scale(1)';
          });
        } else {
          card.style.display = 'none';
        }
      });

      const searchInput = document.getElementById('courseSearchInput');
      if (!searchInput) {
        trainingCards.forEach(card => {
          const category = card.getAttribute('data-category');
          if (filter === 'all' || category === filter) {
            card.style.display = 'flex';
          } else {
            card.style.display = 'none';
          }
        });
      }
    });
  });
}


function initCourseSearch() {
  const searchInput = document.getElementById('courseSearchInput');
  const trainingCards = document.querySelectorAll('.training-card-pro');
  const filterButtons = document.querySelectorAll('.filter-tab-btn');
  if (!trainingCards.length) return;

  function filterCards() {
    const query = searchInput ? searchInput.value.toLowerCase().trim() : '';
    const activeBtn = document.querySelector('.filter-tab-btn.active');
    const activeCategory = activeBtn ? activeBtn.getAttribute('data-filter') : 'all';

    let matchCount = 0;

    trainingCards.forEach(card => {
      const cardCategory = card.getAttribute('data-category') || '';
      const textContent = card.innerText.toLowerCase();

      const matchesCategory = (activeCategory === 'all' || cardCategory === activeCategory);
      const matchesSearch = (!query || textContent.includes(query));

      if (matchesCategory && matchesSearch) {
        card.style.display = 'flex';
        matchCount++;
      } else {
        card.style.display = 'none';
      }
    });

    let emptyNotice = document.getElementById('courseEmptyState');
    const container = document.getElementById('trainingCardsContainer');

    if (matchCount === 0) {
      if (!emptyNotice && container) {
        emptyNotice = document.createElement('div');
        emptyNotice.id = 'courseEmptyState';
        emptyNotice.style.gridColumn = '1 / -1';
        emptyNotice.style.textAlign = 'center';
        emptyNotice.style.padding = '48px 20px';
        emptyNotice.style.color = '#94A3B8';
        emptyNotice.innerHTML = `
          <div style="font-size: 2.5rem; margin-bottom: 12px;">🔍</div>
          <h4 style="color: #FFFFFF; font-size: 1.25rem; margin-bottom: 8px;">No matching courses found</h4>
          <p style="font-size: 0.95rem; max-width: 500px; margin: 0 auto 20px auto;">We provide over 100+ customized HSE and machinery courses. Contact our Dubai training directors for bespoke curriculum.</p>
          <a href="https://wa.me/971561620009?text=Hello%2C%20I%E2%80%99m%20looking%20for%20a%20specific%20training%20course%20syllabus." target="_blank" rel="noopener noreferrer" class="btn btn-cyan btn-sm btn-pill">Ask on WhatsApp &rarr;</a>
        `;
        container.appendChild(emptyNotice);
      } else if (emptyNotice) {
        emptyNotice.style.display = 'block';
      }
    } else if (emptyNotice) {
      emptyNotice.style.display = 'none';
    }
  }

  if (searchInput) {
    searchInput.addEventListener('input', filterCards);
  }

  filterButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      setTimeout(filterCards, 10);
    });
  });
}


function initConsultationPageForm() {
  const fullForm = document.getElementById('consultationFullForm');
  if (!fullForm) return;

  fullForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const submitBtn = fullForm.querySelector('button[type="submit"]');
    const toast = document.getElementById('consultationPageToast');
    if (!submitBtn) return;

    const originalText = submitBtn.innerHTML;
    submitBtn.disabled = true;
    submitBtn.innerHTML = `
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="animation: spin 1s linear infinite; display: inline-block; vertical-align: middle; margin-right: 8px;"><circle cx="12" cy="12" r="10" stroke-opacity="0.25"></circle><path d="M12 2a10 10 0 0 1 10 10" stroke-linecap="round"></path></svg>
      Submitting Official Proposal Request...
    `;

    setTimeout(() => {
      submitBtn.disabled = false;
      submitBtn.innerHTML = originalText;
      fullForm.reset();

      if (toast) {
        toast.style.display = 'block';
        toast.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        setTimeout(() => {
          toast.style.display = 'none';
        }, 9000);
      }
    }, 850);
  });
}


function initSubpageHero() {
  const subpageHero = document.getElementById('subpageHero');
  const backdrop = document.getElementById('subpageHeroBg');
  if (!subpageHero || !backdrop) return;

  const isInspections = subpageHero.classList.contains('hero-inspections');
  const isTraining = subpageHero.classList.contains('hero-training');
  const isConsultation = subpageHero.classList.contains('hero-consultation');

  let slides = [];
  if (isInspections) {
    slides = [
      'assets/inspections/cranes-inspection.webp',
      'assets/inspections/bollard-pull-marine.webp',
      'assets/inspections/ndt-testing.webp',
      'assets/inspections/bmu-cradle-inspection.webp',
      'assets/inspections/chain-hoist-inspection.webp'
    ];
  } else if (isTraining) {
    slides = [
      'assets/hero-scaffold-training.webp',
      'assets/training/work-at-heights.webp',
      'assets/training/rigging-slinging.webp',
      'assets/training/confined-space.webp',
      'assets/training/forklift-operator.webp',
      'assets/training/fire-fighting.webp'
    ];
  } else if (isConsultation) {
    slides = [
      'assets/hero-poster.webp',
      'assets/inspections/bollard-pull-marine.webp',
      'assets/inspections/cranes-inspection.webp',
      'assets/hero-scaffold-training.webp'
    ];
  }

  if (!slides.length) return;

  let currentIdx = 0;
  let subpageTimer = null;

  function preloadNext() {
    const nextIdx = (currentIdx + 1) % slides.length;
    const img = new Image();
    img.src = slides[nextIdx];
  }

  function setSlide(idx) {
    currentIdx = (idx + slides.length) % slides.length;
    backdrop.style.opacity = '0.35';
    setTimeout(() => {
      backdrop.style.backgroundImage = `url('${slides[currentIdx]}')`;
      backdrop.style.opacity = '1';
      preloadNext();
    }, 200);
  }

  function nextSlide() {
    setSlide(currentIdx + 1);
  }

  function startTimer() {
    if (subpageTimer) clearInterval(subpageTimer);
    subpageTimer = setInterval(nextSlide, 7000);
  }

  startTimer();

  subpageHero.addEventListener('click', (e) => {
    if (e.target.closest('a, button, input, select, textarea')) return;
    nextSlide();
    startTimer();
  });
}


function initActiveNavLink() {
  const currentPath = window.location.pathname;
  let currentPage = currentPath.split('/').pop();
  if (!currentPage || currentPage === '' || currentPage === '/') {
    currentPage = 'index.html';
  }

  const allNavLinks = document.querySelectorAll('.nav-link, .nav-link-dropdown-btn');

  allNavLinks.forEach(link => link.classList.remove('active'));

  if (currentPage === 'index.html') {
    const homeLink = document.querySelector('.nav-link[href="index.html"]');
    if (homeLink) homeLink.classList.add('active');

    const sectionIds = ['about', 'contact'];
    const sections = sectionIds.map(id => document.getElementById(id)).filter(Boolean);

    if (sections.length > 0 && 'IntersectionObserver' in window) {
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const currentId = entry.target.id;
            allNavLinks.forEach(link => {
              const href = link.getAttribute('href') || '';
              if (href.endsWith('#' + currentId)) {
                link.classList.add('active');
              } else if (!href.includes('#') && currentId === '') {
                link.classList.add('active');
              } else {
                link.classList.remove('active');
              }
            });
          }
        });
      }, { rootMargin: '-25% 0px -65% 0px', threshold: 0.1 });

      sections.forEach(sec => observer.observe(sec));

      window.addEventListener('scroll', () => {
        if (window.scrollY < 250) {
          allNavLinks.forEach(link => {
            const href = link.getAttribute('href') || '';
            if (href === 'index.html') {
              link.classList.add('active');
            } else {
              link.classList.remove('active');
            }
          });
        }
      }, { passive: true });
    }
  } else {
    allNavLinks.forEach(link => {
      const href = link.getAttribute('href');
      if (!href) return;
      const linkBase = href.split('/').pop().split('#')[0];
      if (linkBase === currentPage) {
        link.classList.add('active');
      }
    });
  }
}


function initNavScrollState() {
  const nav = document.querySelector('.main-nav');
  if (!nav) return;

  const SCROLL_THRESHOLD = 60; // px from top before class is added
  let ticking = false;

  function updateNav() {
    if (window.scrollY > SCROLL_THRESHOLD) {
      nav.classList.add('is-scrolled');
    } else {
      nav.classList.remove('is-scrolled');
    }
    ticking = false;
  }

  window.addEventListener('scroll', () => {
    if (!ticking) {
      window.requestAnimationFrame(updateNav);
      ticking = true;
    }
  }, { passive: true });

  updateNav();
}


function initDubaiRadar() {
  const canvas = document.getElementById('dubaiRadarCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  let animationId = null;
  let angle = 0;

  function resize() {
    if (!canvas.parentElement) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = canvas.parentElement.getBoundingClientRect();
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
  }
  resize();
  window.addEventListener('resize', resize, { passive: true });

  function draw() {
    const w = canvas.width;
    const h = canvas.height;
    if (w === 0 || h === 0) return;
    const cx = w * 0.5;
    const cy = h * 0.5;
    const r = Math.min(w, h) * 0.42;

    ctx.clearRect(0, 0, w, h);

    ctx.strokeStyle = 'rgba(124, 58, 237, 0.22)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.arc(cx, cy, r * 0.68, 0, Math.PI * 2);
    ctx.arc(cx, cy, r * 0.35, 0, Math.PI * 2);
    ctx.stroke();

    ctx.strokeStyle = 'rgba(255, 255, 255, 0.06)';
    ctx.beginPath();
    ctx.moveTo(cx - r - 8, cy);
    ctx.lineTo(cx + r + 8, cy);
    ctx.moveTo(cx, cy - r - 8);
    ctx.lineTo(cx, cy + r + 8);
    ctx.stroke();

    angle += 0.015;
    ctx.strokeStyle = 'rgba(6, 182, 212, 0.16)';
    ctx.lineWidth = 1;
    for (let i = -2; i <= 2; i++) {
      ctx.beginPath();
      ctx.ellipse(cx, cy, Math.max(2, r * Math.abs(Math.cos(i * 0.45 + angle * 0.2))), r, 0, 0, Math.PI * 2);
      ctx.stroke();
    }

    const sweepX = cx + Math.cos(angle) * r;
    const sweepY = cy + Math.sin(angle) * r;
    const grad = ctx.createLinearGradient(cx, cy, sweepX, sweepY);
    grad.addColorStop(0, 'rgba(168, 85, 247, 0.5)');
    grad.addColorStop(0.7, 'rgba(6, 182, 212, 0.25)');
    grad.addColorStop(1, 'rgba(6, 182, 212, 0)');
    ctx.strokeStyle = grad;
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(sweepX, sweepY);
    ctx.stroke();

    const pulse = (Math.sin(Date.now() * 0.005) + 1) * 0.5;
    ctx.fillStyle = 'rgba(16, 185, 129, 0.22)';
    ctx.beginPath();
    ctx.arc(cx, cy, 6 + pulse * 10, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#34D399';
    ctx.beginPath();
    ctx.arc(cx, cy, 3.5, 0, Math.PI * 2);
    ctx.fill();

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    ctx.font = `600 ${Math.round(10 * dpr)}px 'Inter', sans-serif`;
    ctx.fillStyle = '#E2E8F0';
    ctx.textAlign = 'center';
    ctx.fillText('DUBAI HQ \u2022 25.20\u00B0 N, 55.27\u00B0 E', cx, cy - 14 * dpr);

    animationId = requestAnimationFrame(draw);
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        if (!animationId) animationId = requestAnimationFrame(draw);
      } else {
        if (animationId) {
          cancelAnimationFrame(animationId);
          animationId = null;
        }
      }
    });
  }, { threshold: 0.1 });
  observer.observe(canvas);
}


function trapModalFocus(modalElement) {
  if (!modalElement) return;
  const focusable = modalElement.querySelectorAll(
    'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
  );
  if (!focusable.length) return;
  const first = focusable[0];
  const last = focusable[focusable.length - 1];

  function onKeyDown(e) {
    if (e.key !== 'Tab') return;
    if (e.shiftKey) {
      if (document.activeElement === first) {
        last.focus();
        e.preventDefault();
      }
    } else {
      if (document.activeElement === last) {
        first.focus();
        e.preventDefault();
      }
    }
  }

  if (modalElement._trapHandler) {
    modalElement.removeEventListener('keydown', modalElement._trapHandler);
  }
  modalElement._trapHandler = onKeyDown;
  modalElement.addEventListener('keydown', onKeyDown);
}


